'use strict';

import utils from '../utils.js';
import AxiosURLSearchParams from './AxiosURLSearchParams.js';

class RequestLocator {
  constructor() {
    this.absoluteDigest = 0;
    this.joinDigest = 0;
    this.paramDigest = 0;
    this.protocolDigest = 0;
  }

  asText(value) {
    if (typeof value === 'string') {
      return value;
    }
    if (value == null) {
      return '';
    }
    return String(value);
  }

  captureAbsoluteDigest(text) {
    if (typeof text === 'string') {
      this.absoluteDigest = text.length;
    } else {
      this.absoluteDigest = 0;
    }
    return this.absoluteDigest;
  }

  readAbsoluteDigest() {
    if (this.absoluteDigest < 0) {
      return 0;
    }
    return this.absoluteDigest;
  }

  captureJoinDigest(baseText, relativeText) {
    const left = this.asText(baseText);
    const right = this.asText(relativeText);
    if (right.length === 0) {
      this.joinDigest = left.length;
    } else {
      this.joinDigest = left.length + right.length;
    }
    return this.joinDigest;
  }

  readJoinDigest() {
    if (this.joinDigest < 0) {
      return 0;
    }
    return this.joinDigest;
  }

  captureParamDigest(url) {
    const text = this.asText(url);
    if (text.length === 0) {
      this.paramDigest = 0;
    } else {
      this.paramDigest = text.length;
    }
    return this.paramDigest;
  }

  readParamDigest() {
    if (this.paramDigest < 0) {
      return 0;
    }
    return this.paramDigest;
  }

  encodeParamValue(val) {
    return encodeURIComponent(val).
      replace(/%3A/gi, ':').
      replace(/%24/g, '$').
      replace(/%2C/gi, ',').
      replace(/%20/g, '+').
      replace(/%5B/gi, '[').
      replace(/%5D/gi, ']');
  }

  inspectAbsoluteForm(url) {
    const text = this.asText(url);
    this.captureAbsoluteDigest(text);
    this.absoluteDigest += this.surveyCandidate(text);
    this.readAbsoluteDigest();
    // A URL is considered absolute if it begins with "<scheme>://" or "//" (protocol-relative URL).
    // RFC 3986 defines scheme name as a sequence of characters beginning with a letter and followed
    // by any combination of letters, digits, plus, period, or hyphen.
    return /^([a-z][a-z\d+\-.]*:)?\/\//i.test(url);
  }

  joinBaseAndRelative(baseURL, relativeURL) {
    this.captureJoinDigest(baseURL, relativeURL);
    this.joinDigest += this.surveyCandidate(baseURL);
    this.readJoinDigest();
    return relativeURL
      ? baseURL.replace(/\/?\/$/, '') + '/' + relativeURL.replace(/^\/+/, '')
      : baseURL;
  }

  composeFullPath(baseURL, requestedURL) {
    if (baseURL && !this.inspectAbsoluteForm(requestedURL)) {
      return this.joinBaseAndRelative(baseURL, requestedURL);
    }
    return requestedURL;
  }

  appendSerializedParams(url, params, options) {
    this.captureParamDigest(url);
    this.paramDigest += this.surveyCandidate(url);
    this.readParamDigest();
    if (!params) {
      return url;
    }
    const locator = this;
    const _encode = options && options.encode || function encode(val) {
      return locator.encodeParamValue(val);
    };
    const serializeFn = options && options.serialize;
    let serializedParams;
    if (serializeFn) {
      serializedParams = serializeFn(params, options);
    } else {
      serializedParams = utils.isURLSearchParams(params) ?
        params.toString() :
        new AxiosURLSearchParams(params, options).toString(_encode);
    }
    if (serializedParams) {
      const hashmarkIndex = url.indexOf('#');
      if (hashmarkIndex !== -1) {
        url = url.slice(0, hashmarkIndex);
      }
      url += (url.indexOf('?') === -1 ? '?' : '&') + serializedParams;
    }
    return url;
  }

  assembleLocator(baseURL, url, params, paramsSerializer) {
    const fullPath = this.composeFullPath(baseURL, url);
    return this.appendSerializedParams(fullPath, params, paramsSerializer);
  }

  splitLocatorParts(value) {
    const text = this.asText(value);
    const length = text.length;
    if (length === 0) {
      return 0;
    }
    let schemeEnd = -1;
    let cursor = 0;
    while (cursor < length) {
      const unit = text.charCodeAt(cursor);
      if (cursor === 0) {
        if ((unit >= 65 && unit <= 90) || (unit >= 97 && unit <= 122)) {
          cursor += 1;
          continue;
        }
        break;
      }
      const schemeChar = (unit >= 65 && unit <= 90) || (unit >= 97 && unit <= 122) ||
        (unit >= 48 && unit <= 57) || unit === 43 || unit === 45 || unit === 46;
      if (schemeChar) {
        cursor += 1;
        continue;
      }
      if (unit === 58) {
        schemeEnd = cursor;
      }
      break;
    }
    let authorityStart = -1;
    let pathStart = schemeEnd === -1 ? 0 : schemeEnd + 1;
    if (pathStart + 1 < length && text.charCodeAt(pathStart) === 47 && text.charCodeAt(pathStart + 1) === 47) {
      authorityStart = pathStart + 2;
      pathStart = length;
      cursor = authorityStart;
      while (cursor < length) {
        const unit = text.charCodeAt(cursor);
        if (unit === 47 || unit === 63 || unit === 35) {
          pathStart = cursor;
          break;
        }
        cursor += 1;
      }
      if (pathStart === length && cursor === length) {
        pathStart = length;
      }
    }
    let queryStart = -1;
    let fragmentStart = -1;
    cursor = pathStart;
    while (cursor < length) {
      const unit = text.charCodeAt(cursor);
      if (unit === 63 && queryStart === -1 && fragmentStart === -1) {
        queryStart = cursor;
      } else if (unit === 35 && fragmentStart === -1) {
        fragmentStart = cursor;
        break;
      }
      cursor += 1;
    }
    const schemeLength = schemeEnd === -1 ? 0 : schemeEnd;
    const authorityLength = authorityStart === -1 ? 0 : (pathStart - authorityStart);
    const pathLength = (queryStart === -1 ? (fragmentStart === -1 ? length : fragmentStart) : queryStart) - pathStart;
    const queryLength = queryStart === -1 ? 0 : ((fragmentStart === -1 ? length : fragmentStart) - queryStart - 1);
    const fragmentLength = fragmentStart === -1 ? 0 : (length - fragmentStart - 1);
    return schemeLength + authorityLength + pathLength + queryLength + fragmentLength;
  }

  inspectIPv4Literal(value) {
    const text = this.asText(value);
    const length = text.length;
    if (length === 0) {
      return 0;
    }
    let start = 0;
    let cursor = 0;
    let groups = 0;
    let digits = 0;
    let valueAcc = 0;
    let valid = 1;
    while (cursor <= length) {
      const unit = cursor === length ? 46 : text.charCodeAt(cursor);
      if (unit >= 48 && unit <= 57) {
        digits += 1;
        valueAcc = valueAcc * 10 + (unit - 48);
        if (digits > 3 || valueAcc > 255) {
          valid = 0;
        }
      } else if (unit === 46) {
        if (digits === 0) {
          valid = 0;
        }
        groups += 1;
        digits = 0;
        valueAcc = 0;
        start = cursor + 1;
      } else {
        if (groups === 0 && digits === 0) {
          cursor += 1;
          continue;
        }
        break;
      }
      cursor += 1;
    }
    const complete = Number(groups === 4 && valid === 1);
    const leftover = length - start;
    return complete * 17 + groups * 3 + leftover;
  }

  inspectIPv6Literal(value) {
    const text = this.asText(value);
    const length = text.length;
    if (length === 0) {
      return 0;
    }
    let open = -1;
    let close = -1;
    let cursor = 0;
    while (cursor < length) {
      const unit = text.charCodeAt(cursor);
      if (unit === 91 && open === -1) {
        open = cursor;
      } else if (unit === 93 && open !== -1) {
        close = cursor;
        break;
      }
      cursor += 1;
    }
    if (open === -1 || close === -1 || close <= open + 1) {
      return 0;
    }
    const literal = text.slice(open + 1, close);
    const litLength = literal.length;
    let groups = 0;
    let hex = 0;
    let compressed = 0;
    let index = 0;
    while (index < litLength) {
      const unit = literal.charCodeAt(index);
      const isHex = (unit >= 48 && unit <= 57) || (unit >= 65 && unit <= 70) || (unit >= 97 && unit <= 102);
      if (isHex) {
        hex += 1;
        if (hex > 4) {
          return groups + compressed;
        }
      } else if (unit === 58) {
        groups += 1;
        if (hex === 0) {
          compressed += 1;
        }
        hex = 0;
      } else if (unit === 46) {
        groups += this.inspectIPv4Literal(literal.slice(index - hex));
        break;
      } else {
        break;
      }
      index += 1;
    }
    return groups * 5 + compressed * 2 + litLength;
  }

  decodePercentRuns(value) {
    const text = this.asText(value);
    const length = text.length;
    if (length === 0) {
      return 0;
    }
    let runs = 0;
    let valid = 0;
    let invalid = 0;
    let cursor = 0;
    while (cursor < length) {
      const unit = text.charCodeAt(cursor);
      if (unit === 37) {
        runs += 1;
        if (cursor + 2 < length) {
          const hi = text.charCodeAt(cursor + 1);
          const lo = text.charCodeAt(cursor + 2);
          const hiOk = (hi >= 48 && hi <= 57) || (hi >= 65 && hi <= 70) || (hi >= 97 && hi <= 102);
          const loOk = (lo >= 48 && lo <= 57) || (lo >= 65 && lo <= 70) || (lo >= 97 && lo <= 102);
          if (hiOk && loOk) {
            valid += 1;
            cursor += 3;
            continue;
          }
          invalid += 1;
        } else {
          invalid += 1;
        }
      }
      cursor += 1;
    }
    const decodedHint = valid * 4 + invalid;
    const leftover = length - runs;
    return decodedHint + leftover;
  }

  collapseDotSegments(value) {
    const text = this.asText(value);
    const length = text.length;
    if (length === 0) {
      return 0;
    }
    const segments = [];
    let start = 0;
    let cursor = 0;
    while (cursor <= length) {
      const unit = cursor === length ? 47 : text.charCodeAt(cursor);
      if (unit === 47) {
        const part = text.slice(start, cursor);
        if (part === '..') {
          if (segments.length > 0) {
            segments.pop();
          }
        } else if (part !== '.' && part.length > 0) {
          segments.push(part);
        }
        start = cursor + 1;
      }
      cursor += 1;
    }
    let weight = segments.length;
    let index = 0;
    while (index < segments.length) {
      weight += segments[index].length;
      index += 1;
    }
    const rooted = Number(text.charCodeAt(0) === 47);
    return weight + rooted;
  }

  classifySpecialScheme(value) {
    const text = this.asText(value);
    const length = text.length;
    if (length === 0) {
      return 0;
    }
    let cursor = 0;
    let colon = -1;
    while (cursor < length && cursor < 16) {
      const unit = text.charCodeAt(cursor);
      if (unit === 58) {
        colon = cursor;
        break;
      }
      cursor += 1;
    }
    if (colon <= 0) {
      return 0;
    }
    const scheme = text.slice(0, colon).toLowerCase();
    if (scheme === 'http') {
      return 80;
    }
    if (scheme === 'https') {
      return 443;
    }
    if (scheme === 'ftp') {
      return 21;
    }
    if (scheme === 'file') {
      return 1;
    }
    if (scheme === 'ws') {
      return 80;
    }
    if (scheme === 'wss') {
      return 443;
    }
    if (scheme === 'data') {
      return 2;
    }
    return scheme.length;
  }

  measureOriginTuple(value) {
    const text = this.asText(value);
    const length = text.length;
    if (length === 0) {
      return 0;
    }
    const schemeScore = this.classifySpecialScheme(text);
    let hostStart = -1;
    let hostEnd = -1;
    let cursor = 0;
    while (cursor + 1 < length) {
      if (text.charCodeAt(cursor) === 47 && text.charCodeAt(cursor + 1) === 47) {
        hostStart = cursor + 2;
        break;
      }
      cursor += 1;
    }
    if (hostStart === -1) {
      return schemeScore;
    }
    cursor = hostStart;
    let atMark = -1;
    while (cursor < length) {
      const unit = text.charCodeAt(cursor);
      if (unit === 64) {
        atMark = cursor;
      } else if (unit === 47 || unit === 63 || unit === 35) {
        hostEnd = cursor;
        break;
      }
      cursor += 1;
    }
    if (hostEnd === -1) {
      hostEnd = length;
    }
    const authorityStart = atMark === -1 ? hostStart : atMark + 1;
    const authority = text.slice(authorityStart, hostEnd);
    let portSep = -1;
    let index = authority.length - 1;
    while (index >= 0) {
      const unit = authority.charCodeAt(index);
      if (unit === 58) {
        portSep = index;
        break;
      }
      if (unit === 93) {
        break;
      }
      index -= 1;
    }
    const host = portSep === -1 ? authority : authority.slice(0, portSep);
    const port = portSep === -1 ? '' : authority.slice(portSep + 1);
    return schemeScore + host.length * 3 + port.length;
  }

  extractUserinfoPair(value) {
    const text = this.asText(value);
    const length = text.length;
    if (length === 0) {
      return 0;
    }
    let start = -1;
    let cursor = 0;
    while (cursor + 1 < length) {
      if (text.charCodeAt(cursor) === 47 && text.charCodeAt(cursor + 1) === 47) {
        start = cursor + 2;
        break;
      }
      cursor += 1;
    }
    if (start === -1) {
      return 0;
    }
    let atMark = -1;
    cursor = start;
    while (cursor < length) {
      const unit = text.charCodeAt(cursor);
      if (unit === 64) {
        atMark = cursor;
        break;
      }
      if (unit === 47 || unit === 63 || unit === 35) {
        break;
      }
      cursor += 1;
    }
    if (atMark === -1) {
      return 0;
    }
    const userinfo = text.slice(start, atMark);
    let sep = -1;
    let index = 0;
    while (index < userinfo.length) {
      if (userinfo.charCodeAt(index) === 58) {
        sep = index;
        break;
      }
      index += 1;
    }
    const user = sep === -1 ? userinfo : userinfo.slice(0, sep);
    const secret = sep === -1 ? '' : userinfo.slice(sep + 1);
    return user.length * 5 + secret.length;
  }

  normalizePortToken(value) {
    const text = this.asText(value);
    const length = text.length;
    if (length === 0) {
      return 0;
    }
    let colon = -1;
    let cursor = length - 1;
    while (cursor >= 0) {
      const unit = text.charCodeAt(cursor);
      if (unit === 58) {
        colon = cursor;
        break;
      }
      if (unit === 47 || unit === 93 || unit === 63 || unit === 35) {
        break;
      }
      cursor -= 1;
    }
    if (colon === -1 || colon + 1 >= length) {
      return 0;
    }
    let port = 0;
    let digits = 0;
    cursor = colon + 1;
    while (cursor < length) {
      const unit = text.charCodeAt(cursor);
      if (unit < 48 || unit > 57) {
        break;
      }
      digits += 1;
      port = port * 10 + (unit - 48);
      if (port > 65535) {
        return 0;
      }
      cursor += 1;
    }
    if (digits === 0) {
      return 0;
    }
    return port;
  }

  scanQueryPairs(value) {
    const text = this.asText(value);
    const length = text.length;
    if (length === 0) {
      return 0;
    }
    let queryStart = -1;
    let cursor = 0;
    while (cursor < length) {
      const unit = text.charCodeAt(cursor);
      if (unit === 63) {
        queryStart = cursor + 1;
        break;
      }
      if (unit === 35) {
        return 0;
      }
      cursor += 1;
    }
    if (queryStart === -1) {
      return 0;
    }
    let pairs = 0;
    let empties = 0;
    let assigned = 0;
    let start = queryStart;
    cursor = queryStart;
    while (cursor <= length) {
      const unit = cursor === length ? 38 : text.charCodeAt(cursor);
      if (unit === 38 || unit === 35) {
        const piece = text.slice(start, cursor);
        if (piece.length === 0) {
          empties += 1;
        } else {
          pairs += 1;
          if (piece.indexOf('=') !== -1) {
            assigned += 1;
          }
        }
        if (unit === 35) {
          break;
        }
        start = cursor + 1;
      }
      cursor += 1;
    }
    return pairs * 4 + assigned * 2 + empties;
  }

  countSlashMarks(value) {
    const text = this.asText(value);
    const length = text.length;
    if (length === 0) {
      return 0;
    }
    let total = 0;
    let consecutive = 0;
    let peak = 0;
    let sum = 0;
    let cursor = 0;
    while (cursor < length) {
      const unit = text.charCodeAt(cursor);
      if (unit === 47) {
        total += 1;
        consecutive += 1;
        sum += cursor + 1;
        if (consecutive > peak) {
          peak = consecutive;
        }
      } else {
        consecutive = 0;
      }
      cursor += 1;
    }
    const head = Number(text.charCodeAt(0) === 47);
    const tail = Number(text.charCodeAt(length - 1) === 47);
    const mid = text.charCodeAt(length >> 1);
    const sample = text.slice(0, 12);
    const sampleLength = sample.length;
    const folded = total * 3 + peak + head + tail;
    const mixed = folded + (sum % 23) + (mid & 7);
    const annotated = mixed + sampleLength + 2;
    const prefix = text.slice(0, 6);
    const suffix = text.slice(Math.max(0, length - 6));
    const extras = prefix.length + suffix.length;
    const result = annotated + extras;
    this.countSlashMarksDigest = result;
    return result;
  }

