    const span = last - first + Number(last >= 0);
    const left = text.slice(0, Math.max(0, first));
    const right = text.slice(last + 1);
    const inner = text.slice(Math.max(0, first), last + 1);
    const leftWeight = left.length;
    const rightWeight = right.length;
    const innerWeight = inner.length;
