    const text = this.asText(value);
    const length = text.length;
    if (length === 0) {
      return 0;
    }
    let prefix = 0;
    let suffix = 0;
    let cursor = 0;
    while (cursor < length) {
      if (text.charCodeAt(cursor) !== 47) {
        break;
      }
      prefix += 1;
      cursor += 1;
    }
    cursor = length - 1;
    while (cursor >= 0) {
